/// region <Save>

TEST_F(LoaderMGT_Test, Save_RoundTrip)
{
    std::vector<uint8_t> mgtBytes = readFile(fixture("loaders/mgt/synthetic.mgt"));
    std::vector<uint8_t> imgBytes = readFile(fixture("loaders/mgt/synthetic.img"));
    ASSERT_EQ(mgtBytes.size(), 819200u);
    ASSERT_EQ(imgBytes.size(), 819200u);

    struct Case { const char* source; const char* target; const std::vector<uint8_t>* expected; };
    const Case cases[] = {
        { "loaders/mgt/synthetic.mgt", "roundtrip.mgt", &mgtBytes },   // .mgt -> .mgt
        { "loaders/mgt/synthetic.mgt", "roundtrip.img", &imgBytes },   // .mgt -> .img (reordered on save)
        { "loaders/mgt/synthetic.img", "roundtrip.img", &imgBytes },   // .img -> .img
        { "loaders/mgt/synthetic.img", "roundtrip.mgt", &mgtBytes },   // .img -> .mgt
    };

    for (const Case& c : cases)
    {
        std::string target = scratch(c.target);
        removeFile(target);

        LoaderMGT loader(_context, fixture(c.source));
        ASSERT_TRUE(loader.loadImage()) << c.source;
        DiskImage* image = loader.getImage();

        // Touch the image (write a sector, then write the original back) so that the save has something to clean
        {
            DiskImage::Track* track = image->getTrackForCylinderAndSide(0, 0);
            std::vector<uint8_t> original(track->getSector(0)->data, track->getSector(0)->data + 512);
            std::vector<uint8_t> modified(original);
            modified[100] ^= 0xFF;
            track->writeSectorData(0, modified.data(), modified.size());
            track->writeSectorData(0, original.data(), original.size());
        }
        ASSERT_TRUE(image->isDirty());

        ASSERT_TRUE(loader.writeImage(target)) << c.source << " -> " << c.target << ": " << join(loader.lastWarnings(), "; ");
        EXPECT_TRUE(loader.lastWarnings().empty());
        EXPECT_FALSE(image->isDirty());
        EXPECT_EQ(image->getFilePath(), target);

        std::vector<uint8_t> out = readFile(target);
        ASSERT_EQ(out.size(), c.expected->size()) << c.source << " -> " << c.target;
        EXPECT_EQ(std::memcmp(out.data(), c.expected->data(), out.size()), 0) << c.source << " -> " << c.target << " differs after round trip";

        removeFile(target);
        delete image;
    }

    // In-memory: serialize in both orders straight from one image, and the override wins over the extension
    LoaderMGT loader(_context, fixture("loaders/mgt/synthetic.mgt"));
    ASSERT_TRUE(loader.loadImage());
    DiskImage* image = loader.getImage();

    std::vector<uint8_t> out;
    std::vector<std::string> warnings;
    ASSERT_TRUE(loader.serialize(image, TrackOrder::CylinderMajor, out, warnings));
    EXPECT_EQ(out, mgtBytes);
    ASSERT_TRUE(loader.serialize(image, TrackOrder::SideMajor, out, warnings));
    EXPECT_EQ(out, imgBytes);

    std::string target = scratch("override.mgt");
    removeFile(target);
    loader.setTrackOrder(TrackOrder::SideMajor);
    ASSERT_TRUE(loader.writeImage(target));
    EXPECT_EQ(readFile(target), imgBytes) << "setTrackOrder(SideMajor) must win over the .mgt extension";
    removeFile(target);

    delete image;
}

TEST_F(LoaderMGT_Test, WriteImage_RefusesNonPlusDGeometry)
{
    std::string target = scratch("refused.mgt");

    // Default DiskImage = 16 x 256 TR-DOS tracks
    {
        removeFile(target);
        DiskImage image(80, 2);
        LoaderMGT loader(_context, target);
        loader.setImage(&image);

        std::string reason;
        EXPECT_FALSE(LoaderMGT::isPlusDGeometry(&image, &reason));
        EXPECT_FALSE(reason.empty());

        EXPECT_FALSE(loader.writeImage(target));
        ASSERT_FALSE(loader.lastWarnings().empty());
        EXPECT_NE(loader.lastWarnings().front().find("refused"), std::string::npos) << loader.lastWarnings().front();
        EXPECT_FALSE(FileHelper::FileExists(target)) << "nothing must be written";
    }

    // Right sectors but a single side
    {
        DiskImage image(80, 1, Spec::plusD());
        LoaderMGT loader(_context, target);
        loader.setImage(&image);
        EXPECT_FALSE(loader.writeImage(target));
        EXPECT_FALSE(loader.lastWarnings().empty());
        EXPECT_FALSE(FileHelper::FileExists(target));
    }

    // Right sectors but 41 cylinders
    {
        DiskImage image(41, 2, Spec::plusD());
        LoaderMGT loader(_context, target);
        loader.setImage(&image);
        EXPECT_FALSE(loader.writeImage(target));
        EXPECT_FALSE(FileHelper::FileExists(target));
    }

    // 9 x 512 (+3 layout) on one track of an otherwise valid image
    {
        DiskImage image(80, 2, Spec::plusD());
        EXPECT_TRUE(LoaderMGT::isPlusDGeometry(&image));
        image.getTrackForCylinderAndSide(17, 1)->formatTrack(17, 1, Spec::plus3());

        std::string reason;
        EXPECT_FALSE(LoaderMGT::isPlusDGeometry(&image, &reason));
        EXPECT_NE(reason.find("17"), std::string::npos) << reason;

        LoaderMGT loader(_context, target);
        loader.setImage(&image);
        EXPECT_FALSE(loader.writeImage(target));
        EXPECT_FALSE(FileHelper::FileExists(target));
        EXPECT_FALSE(image.isDirty()) << "a refused save leaves the dirty state alone";
    }

    // No image at all
    {
        LoaderMGT loader(_context, target);
        EXPECT_FALSE(loader.writeImage(target));
        EXPECT_FALSE(loader.lastWarnings().empty());
    }

    // A blank +D image saves fine (all zero) - proves the refusal above is about geometry, not content
    {
        removeFile(target);
        DiskImage image(80, 2, Spec::plusD());
        LoaderMGT loader(_context, target);
        loader.setImage(&image);
        ASSERT_TRUE(loader.writeImage(target)) << join(loader.lastWarnings(), "; ");
        std::vector<uint8_t> out = readFile(target);
        ASSERT_EQ(out.size(), 819200u);
        EXPECT_TRUE(std::all_of(out.begin(), out.end(), [](uint8_t b) { return b == 0; }));
        removeFile(target);
    }
}

