/// region <Controller>

/// READ SECTOR on a +D track through the WD1793 returns the full 512-byte data field
TEST_F(LoaderMGT_Test, Wd1793_ReadSector_512)
{
    LoaderMGT loader(_context, fixture("loaders/mgt/synthetic.mgt"));
    ASSERT_TRUE(loader.loadImage());
    DiskImage* image = loader.getImage();

    auto readSector = [&](uint8_t cyl, uint8_t side, uint8_t number) -> std::vector<uint8_t>
    {
        WD1793CUT fdc(_context);
        fdc.getDrive()->insertDisk(image);
        fdc._beta128Register = WD1793CUT::BETA128_COMMAND_BITS::BETA_CMD_RESET;   // MFM (DENSITY bit clear)
        fdc._drive = 0;
        fdc.wakeUp();
        fdc._time = 1000;
        fdc.prolongFDDMotorRotation();
        fdc._trackRegister = cyl;
        fdc._selectedDrive->setTrack(cyl);
        fdc._sideUp = side != 0;
        fdc._sectorRegister = number;
        fdc._commandRegister = 0x80;
        fdc._lastDecodedCmd = WD1793::WD_CMD_READ_SECTOR;
        fdc.cmdReadSector(0x00);

        std::vector<uint8_t> read;
        for (size_t clk = 1000; clk < 1000 + 3'500'000 * 3 && fdc._state != WD1793::S_IDLE; clk += 100)
        {
            fdc._time = clk;
            fdc.process();
            if (fdc._beta128status & WD1793::DRQ) read.push_back(fdc.readDataRegister());
        }
        EXPECT_EQ(fdc._state, WD1793::S_IDLE) << "READ SECTOR did not finish within 3 seconds";
        EXPECT_FALSE(fdc._statusRegister & WD1793::WDS_NOTFOUND);
        EXPECT_FALSE(fdc._statusRegister & WD1793::WDS_CRCERR);
        fdc.getDrive()->ejectDisk();
        return read;
    };

    // Sector 10 (the last one on the track) on cylinder 3 side 0
    std::vector<uint8_t> data = readSector(3, 0, 10);
    ASSERT_EQ(data.size(), 512u);
    EXPECT_EQ(data, expectedSector(3, 0, 10));

    // Sector 1 on cylinder 79 side 1
    data = readSector(79, 1, 1);
    ASSERT_EQ(data.size(), 512u);
    EXPECT_EQ(data, expectedSector(79, 1, 1));

    // Sector 11 does not exist on a +D track
    {
        WD1793CUT fdc(_context);
        fdc.getDrive()->insertDisk(image);
        fdc._beta128Register = WD1793CUT::BETA128_COMMAND_BITS::BETA_CMD_RESET;
        fdc._drive = 0;
        fdc.wakeUp();
        fdc._time = 1000;
        fdc.prolongFDDMotorRotation();
        fdc._trackRegister = 3;
        fdc._selectedDrive->setTrack(3);
        fdc._sideUp = false;
        fdc._sectorRegister = 11;
        fdc._commandRegister = 0x80;
        fdc._lastDecodedCmd = WD1793::WD_CMD_READ_SECTOR;
        fdc.cmdReadSector(0x00);
        for (size_t clk = 1000; clk < 1000 + 3'500'000 * 3 && fdc._state != WD1793::S_IDLE; clk += 100)
        {
            fdc._time = clk;
            fdc.process();
            if (fdc._beta128status & WD1793::DRQ) fdc.readDataRegister();
        }
        EXPECT_EQ(fdc._state, WD1793::S_IDLE);
        EXPECT_TRUE(fdc._statusRegister & WD1793::WDS_NOTFOUND);
        fdc.getDrive()->ejectDisk();
    }

    delete image;
}

/// endregion </Controller>
